  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <div id="root"></div>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel relaxed, but purring can also be a way to self-soothe when they are stressed, recovering, or asking for attention."
        },
        {
          question: "How often should I feed my cat?",
          answer:
            "Most adult cats do well with measured meals two times a day. Kittens, senior cats, and cats with medical needs may need a schedule recommended by a veterinarian."
        },
        {
          question: "Do indoor cats need enrichment?",
          answer:
            "Yes. Indoor cats benefit from climbing spaces, scratching posts, puzzle feeders, play sessions, and safe window views that let them exercise natural behaviors."
        },
        {
          question: "Why does my cat knead blankets?",
          answer:
            "Kneading is a comforting behavior that begins in kittenhood. Many cats keep doing it when they feel secure, sleepy, or affectionate."
        },
        {
          question: "How can I make vet visits less stressful?",
          answer:
            "Leave the carrier out at home with soft bedding and treats, practice short car trips, and bring familiar-smelling items. Ask your vet about calming options for anxious cats."
        }
      ];

      function Header() {
        return `
          <header class="site-header">
            <a class="brand" href="#maincontent" aria-label="Cat Care FAQ home">
              <span class="brand-mark" aria-hidden="true">🐾</span>
              <span>Cat Care FAQ</span>
            </a>
            <nav class="site-nav" aria-label="Primary">
              <ul>
                <li><a href="#faq">Questions</a></li>
                <li><a href="#care-note">Care note</a></li>
              </ul>
            </nav>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="hero" aria-labelledby="page-title">
            <div class="hero-card">
              <p class="eyebrow">Practical answers for curious cat people</p>
              <h1 id="page-title">Cat care, simplified.</h1>
              <p class="hero-copy">
                Explore quick, trustworthy answers about common cat behaviors,
                daily routines, and ways to keep your feline companion comfortable.
              </p>
            </div>
            <aside class="stats-card" id="care-note" aria-label="Cat care note">
              <p>Small, consistent routines help cats feel safe and confident.</p>
            </aside>
          </section>
        `;
      }

      function FAQItem(item, index) {
        const buttonId = `faq-button-${index + 1}`;
        const panelId = `faq-panel-${index + 1}`;

        return `
          <div class="example">
            <h3 class="question">
              <button type="button" id="${buttonId}" aria-expanded="true" aria-controls="${panelId}">
                <span>${item.question}</span>
                <span class="indicator" aria-hidden="true">+</span>
              </button>
            </h3>
            <div class="details" id="${panelId}" aria-labelledby="${buttonId}">
              <p>${item.answer}</p>
            </div>
          </div>
        `;
      }

      function FAQSection(items) {
        return `
          <section class="faq-panel" id="faq" aria-labelledby="faq-heading">
            <h2 class="section-heading" id="faq-heading">Frequently asked questions</h2>
            <div class="faq-list">
              ${items.map(FAQItem).join("")}
            </div>
          </section>
        `;
      }

      function Footer() {
        return `
          <footer class="site-footer">
            <p>General guidance only. Contact a veterinarian for health concerns or sudden behavior changes.</p>
          </footer>
        `;
      }

      function App() {
        return `
          ${Header()}
          <main id="maincontent" tabindex="-1">
            ${Hero()}
            ${FAQSection(faqs)}
          </main>
          ${Footer()}
        `;
      }

      function initializeDisclosures() {
        document.querySelectorAll(".example").forEach((item) => {
          const button = item.querySelector("button[aria-expanded]");
          const panel = item.querySelector(".details");

          button.setAttribute("aria-expanded", "false");
          panel.hidden = true;

          button.addEventListener("click", () => {
            const isOpen = button.getAttribute("aria-expanded") === "true";
            button.setAttribute("aria-expanded", String(!isOpen));
            panel.hidden = isOpen;
          });

          button.addEventListener("keydown", (event) => {
            if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
              button.setAttribute("aria-expanded", "false");
              panel.hidden = true;
            }
          });
        });
      }

      document.querySelector("#root").innerHTML = App();
      initializeDisclosures();
    </script>
  </body>
</html>
