const fs = require('fs');
const { chromium } = require('playwright');
const axe = require('axe-core');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(fs.readFileSync('index.html', 'utf8'), { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const result = await page.evaluate(async () => await window.axe.run());
  const collapsed = await page.evaluate(() => Array.from(document.querySelectorAll('.example')).every((item) => {
    const button = item.querySelector('button[aria-expanded]');
    const panel = item.querySelector('.details');
    return button && panel && button.getAttribute('aria-expanded') === 'false' && panel.hidden;
  }));
  const classOk = await page.evaluate(() => document.querySelectorAll('.example').length === 5 && document.querySelectorAll('.example .details').length === 5);
  const toggleWorks = await page.evaluate(() => {
    const item = document.querySelector('.example');
    const button = item.querySelector('button');
    const panel = item.querySelector('.details');
    button.click();
    return button.getAttribute('aria-expanded') === 'true' && !panel.hidden;
  });
  await browser.close();
  const wcag = result.violations.filter((v) => !v.tags.includes('best-practice'));
  const bp = result.violations.filter((v) => v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    bp: bp.map((v) => ({ id: v.id, targets: v.nodes.map((n) => n.target) })),
    collapsedByDefault: collapsed,
    requiredClasses: classOk,
    toggleWorks,
  }, null, 2));
  process.exit(wcag.length || !collapsed || !classOk || !toggleWorks ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
