            <div class="stats-card" id="care-note" aria-label="Cat care note">
              <p>Small, consistent routines help cats feel safe and confident.</p>
            </div>
          </section>
        `;
      }

      function FAQItem(item, index) {
        const buttonId = `faq-button-${index + 1}`;
        const panelId = `faq-panel-${index + 1}`;

        return `
          <div class="example">
            <h3 class="question">
              <button type="button" id="${buttonId}" aria-expanded="true" aria-controls="${panelId}">
                <span>${item.question}</span>
                <span class="indicator" aria-hidden="true">+</span>
              </button>
            </h3>
            <div class="details" id="${panelId}" aria-labelledby="${buttonId}">
              <p>${item.answer}</p>
            </div>
