    bp: bp.map((v) => ({ id: v.id, targets: v.nodes.map((n) => n.target) })),
    collapsedByDefault: collapsed,
    requiredClasses: classOk,
    toggleWorks,
  }, null, 2));
  process.exit(wcag.length || !collapsed || !classOk || !toggleWorks ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
