const fs = require('fs');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(fs.readFileSync('index.html', 'utf8'), { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const result = await page.evaluate(async () => await window.axe.run());
  const checks = await page.evaluate(() => ({
    oneMain: document.querySelectorAll('main').length === 1,
    oneH1: document.querySelectorAll('h1').length === 1,
    skipLinkFirst: document.body.firstElementChild?.matches('a.skip-link[href="#maincontent"]') === true,
    collapsed: Array.from(document.querySelectorAll('.example')).every((item) => {
      const button = item.querySelector('button[aria-expanded]');
      const panel = item.querySelector('.details');
      return button && panel && button.getAttribute('aria-expanded') === 'false' && panel.hidden;
    }),
    requiredClasses: document.querySelectorAll('.example').length === 5 && document.querySelectorAll('.example .details').length === 5,
    toggleWorks: (() => {
      const item = document.querySelector('.example');
      const button = item.querySelector('button');
      const panel = item.querySelector('.details');
      button.click();
      const opened = button.getAttribute('aria-expanded') === 'true' && !panel.hidden;
      button.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
      const closed = button.getAttribute('aria-expanded') === 'false' && panel.hidden;
      return opened && closed;
    })(),
  }));
  await browser.close();
  const wcag = result.violations.filter((v) => !v.tags.includes('best-practice'));
  const bp = result.violations.filter((v) => v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    bp: bp.map((v) => ({ id: v.id, targets: v.nodes.map((n) => n.target) })),
    checks,
  }, null, 2));
  process.exit(wcag.length || Object.values(checks).some((value) => !value) ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
